messages.content:
Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l4-electronic-microcity",
  "level": "L4",
  "title": "Micro-city at 3 AM",
  "purpose": "A detailed electronic arrangement that can become a 90 second creator-led track, balancing groove and atmospheric storytelling.",
  "duration_seconds": 90,
  "section_plan": [
    "empty streets: 8 bars",
    "machines wake: 8 bars",
    "human signal: 8 bars",
    "convergence: 12 bars",
    "dawn hint: 8 bars"
  ],
  "style": [
    "IDM-informed downtempo",
    "organic modulation",
    "spatial rhythm"
  ],
  "mood": [
    "observant",
    "intricate",
    "warm beneath cold surfaces"
  ],
  "must_include": [
    "groove has foreground and background layers",
    "human signal is a memorable motif",
    "convergence develops prior material",
    "automation-ready CC movement"
  ],
  "must_avoid": [
    "random glitch density",
    "unchanged eight-bar loop",
    "sub bass and kick constantly coincide"
  ],
  "instrument_roles": [
    "kick and low percussion",
    "sub bass",
    "micro percussion",
    "harmonic bed",
    "human motif",
    "counter texture",
    "transition layer",
    "dawn color"
  ],
  "delivery": [
    "44 bars",
    "8 to 10 tracks",
    "meaningful density and register changes"
  ],
  "score_focus": [
    "groove hierarchy",
    "sound-role imagination",
    "long-form development",
    "editability"
  ],
  "mode_a": false
}

SKELETON:
{"title":"Micro-city at 3 AM","tempo_map":[{"bar":1,"bpm":116}],"key_map":[{"bar":1,"key":"A minor"}],"sections":[{"id":"empty_streets","name":"empty streets","start_bar":1,"bars":8,"time_signature":"4/4"},{"id":"machines_wake","name":"machines wake","start_bar":9,"bars":8,"time_signature":"4/4"},{"id":"human_signal","name":"human signal","start_bar":17,"bars":8,"time_signature":"4/4"},{"id":"convergence","name":"convergence","start_bar":25,"bars":12,"time_signature":"4/4"},{"id":"dawn_hint","name":"dawn hint","start_bar":33,"bars":8,"time_signature":"4/4"}],"track_plan":[{"id":"kick_low_perc","name":"kick and low percussion","role":"kick and low percussion","register":{"low":35,"high":55},"instrument_hint":"kick drum + low shaker/rim","section_jobs":[{"section_id":"empty_streets","intent":"barely present, single soft kick at phrase end","density":"sparse"},{"section_id":"machines_wake","intent":"establish syncopated kick pattern, low perc offbeats","density":"medium"},{"section_id":"human_signal","intent":"maintain groove, add ghost notes","density":"medium"},{"section_id":"convergence","intent":"layered kick and low perc fills, busier pattern","density":"dense"},{"section_id":"dawn_hint","intent":"kick thins out, low perc becomes gentle","density":"sparse"}]},{"id":"sub_bass","name":"sub bass","role":"sub bass","register":{"low":28,"high":48},"instrument_hint":"sine/triangle sub","section_jobs":[{"section_id":"empty_streets","intent":"long low drone on tonic, very quiet","density":"sparse"},{"section_id":"machines_wake","intent":"enter with offbeat rhythmic sub, avoid kick coincidences","density":"medium"},{"section_id":"human_signal","intent":"follow harmony, occasional octave jumps","density":"medium"},{"section_id":"convergence","intent":"active sub line, syncopated, works around kick","density":"dense"},{"section_id":"dawn_hint","intent":"sustained low root, fading","density":"sparse"}]},{"id":"micro_percussion","name":"micro percussion","role":"micro percussion","register":{"low":60,"high":90},"instrument_hint":"metallic clicks, hats, tiny shakers","section_jobs":[{"section_id":"empty_streets","intent":"scattered ticks, like distant machinery","density":"sparse"},{"section_id":"machines_wake","intent":"build 16th-note pattern with velocity accents","density":"medium"},{"section_id":"human_signal","intent":"interlock with motif, spatial panning","density":"medium"},{"section_id":"convergence","intent":"dense micro-rhythm foreground, fills","density":"dense"},{"section_id":"dawn_hint","intent":"reduce to occasional shimmer","density":"sparse"}]},{"id":"harmonic_bed","name":"harmonic bed","role":"harmonic bed","register":{"low":48,"high":72},"instrument_hint":"warm pad / electric keys","section_jobs":[{"section_id":"empty_streets","intent":"sustained minor chords, sparse voicings","density":"medium"},{"section_id":"machines_wake","intent":"add rhythmic chord stabs, evolving pad","density":"medium"},{"section_id":"human_signal","intent":"support motif with clear progression","density":"medium"},{"section_id":"convergence","intent":"thicker voicings, harmonically richer","density":"dense"},{"section_id":"dawn_hint","intent":"resolve to airy add9 chords, slower changes","density":"medium"}]},{"id":"human_motif","name":"human motif","role":"human motif","register":{"low":60,"high":84},"instrument_hint":"plucked lead / mallet","section_jobs":[{"section_id":"empty_streets","intent":"distant echo hint of motif, one phrase","density":"sparse"},{"section_id":"machines_wake","intent":"fragment preview, two-note cells","density":"sparse"},{"section_id":"human_signal","intent":"featured memorable motif, full phrase","density":"medium"},{"section_id":"convergence","intent":"develop motif: inversion, augmentation, call-response","density":"dense"},{"section_id":"dawn_hint","intent":"soft restatement, legato, fading","density":"medium"}]},{"id":"counter_texture","name":"counter texture","role":"counter texture","register":{"low":55,"high":79},"instrument_hint":"granular texture / washed echoes","section_jobs":[{"section_id":"empty_streets","intent":"soft noise wash, minimal","density":"sparse"},{"section_id":"machines_wake","intent":"occasional reverse swell","density":"sparse"},{"section_id":"human_signal","intent":"counter lines answer motif","density":"medium"},{"section_id":"convergence","intent":"interweaving textures, busier","density":"dense"},{"section_id":"dawn_hint","intent":"thin out to a few high sparkles","density":"sparse"}]},{"id":"transition_layer","name":"transition layer","role":"transition layer","register":{"low":40,"high":80},"instrument_hint":"risers, filtered noise, white noise sweeps","section_jobs":[{"section_id":"empty_streets","intent":"very low filtered noise, slow LFO","density":"sparse"},{"section_id":"machines_wake","intent":"riser into second half, machine wake","density":"medium"},{"section_id":"human_signal","intent":"small fills between phrases","density":"sparse"},{"section_id":"convergence","intent":"build-ups and breakdowns, automate CC11","density":"medium"},{"section_id":"dawn_hint","intent":"gentle air release, high noise fade","density":"medium"}]},{"id":"dawn_color","name":"dawn color","role":"dawn color","register":{"low":72,"high":96},"instrument_hint":"airy bells / soft high strings","section_jobs":[{"section_id":"empty_streets","intent":"barely audible single bell","density":"sparse"},{"section_id":"machines_wake","intent":"occasional high sparkle","density":"sparse"},{"section_id":"human_signal","intent":"add gentle chime behind motif","density":"sparse"},{"section_id":"convergence","intent":"brighter bell accents, more frequent","density":"medium"},{"section_id":"dawn_hint","intent":"featured bright layer, warm high chords","density":"dense"}]}],"motif_strategy":"The human signal is a 5-note pentatonic motif built on A minor with a rising leap and syncopated ending. It is first hinted as a distant echo, then stated fully in the human_signal section. In convergence it is developed through inversion, rhythmic augmentation and call-response with the counter texture. In dawn_hint it returns softly in a higher octave with slower articulation.","harmony_strategy":"Use A minor as the tonal center. empty_streets sits on i and VI with added 9ths. machines_wake introduces III and VII for motion. human_signal follows i - iv - VI - VII, emphasizing the motif's contour. convergence expands to Imaj7 - VIsus2 - IIIadd9 - VIIadd11, with chromatic passing tones. dawn_hint resolves to Am(add9) with a sustained plagal cadence.","groove_strategy":"Layer a foreground and background groove. Kick and low percussion form a syncopated foreground pulse in 4/4, avoiding constant coincidence with sub bass. Sub bass plays offbeat and pushed notes. Micro percussion provides 16th-note spatial detail with velocity accents. The background layer uses pads and textures with slow attack and CC1/CC11 swells. The groove density evolves from sparse to dense and back, with transitions shaped by the transition layer."}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}

